package com.smartresponse.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="donations") public class Donation {@Id @GeneratedValue private UUID id;@Column(length=24) private String donationType;@Column(precision=12,scale=2) private java.math.BigDecimal amount;@Column(length=3,columnDefinition="char(3)") private String currency;@Column(length=1000) private String itemDescription;@Column(length=160) private String targetName;@Column(length=24) private String targetType;@Column(length=24) private String donationStatus="PLEDGED";@Column(name="reporter_id") private UUID reporterId;private Instant createdAt=Instant.now();protected Donation(){}public Donation(String t,java.math.BigDecimal a,String c,String i,String targetName,String targetType,UUID rid){donationType=t;amount=a;currency=c;itemDescription=i;this.targetName=targetName;this.targetType=targetType;reporterId=rid;}public UUID getId(){return id;}public String getDonationType(){return donationType;}public java.math.BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getItemDescription(){return itemDescription;}public String getTargetName(){return targetName;}public String getTargetType(){return targetType;}public String getDonationStatus(){return donationStatus;}public UUID getReporterId(){return reporterId;}public Instant getCreatedAt(){return createdAt;}}
